import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1:]

    def longest_suffix_subgroup(strings):
        suffix_count = defaultdict(int)
        for string in strings:
            for i in range(1, len(string) + 1):
                suffix_count[string[-i:]] += 1

        max_length = 0
        for string in sorted(strings, key=len):
            if suffix_count[string] == 1:
                current_length = 1
                for i in range(1, len(string) + 1):
                    if suffix_count[string[-i:]] > 1:
                        break
                    current_length += 1
                max_length = max(max_length, current_length)

        return max_length

    print(longest_suffix_subgroup(s))

if __name__ == "__main__":
    main()
